-- Right-top info list entries of the game client (admin panel page "Bilgi Paneli").
--
-- The client's native list under the Knight Genie bar shows title buttons that unfold their
-- description when clicked (WIZ_NOTICE type 4, see crates/ko-protocol/src/info_panel.rs). The
-- game server sends every enabled row of this table to the players, in sort_order, and keeps
-- the list in step with the clan premium of each player:
--   * requires_clan_premium = TRUE  -> shown only while the player's clan premium is active
--   * the live "CLAN PREMIUM" entry (with the remaining time) is generated by the server, it has
--     no row here and its title is reserved.
-- Texts are plain ASCII with '|' as the line separator; the CHECKs are the same bounds the
-- server and the panel enforce (ko_protocol::info_panel).
--
-- Idempotent and live-safe: only creates a table / index that do not exist yet.
CREATE TABLE IF NOT EXISTS info_panel_entry (
    id                    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sort_order            INTEGER      NOT NULL DEFAULT 0,
    title                 VARCHAR(24)  NOT NULL,
    description           VARCHAR(255) NOT NULL,
    enabled               BOOLEAN      NOT NULL DEFAULT TRUE,
    requires_clan_premium BOOLEAN      NOT NULL DEFAULT FALSE,
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT info_panel_entry_title_chk CHECK (char_length(btrim(title)) BETWEEN 1 AND 24),
    CONSTRAINT info_panel_entry_desc_chk  CHECK (char_length(btrim(description)) BETWEEN 1 AND 255)
);

CREATE INDEX IF NOT EXISTS idx_info_panel_entry_order ON info_panel_entry (sort_order, id);

-- Entries of the old C++-style RIGHT_TOP_TITLE table (empty on the live server, never sent by
-- this server) become panel entries once, when the new table is still empty. Rows that do not
-- fit the bounds are cut / skipped, the panel page shows what was taken over.
DO $$
BEGIN
  IF to_regclass('public.right_top_title') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM info_panel_entry) THEN
    INSERT INTO info_panel_entry (sort_order, title, description)
    SELECT (row_number() OVER (ORDER BY id)) * 10,
           left(btrim(str_title), 24),
           left(btrim(str_message), 255)
      FROM right_top_title
     WHERE btrim(coalesce(str_title, '')) <> '' AND btrim(coalesce(str_message, '')) <> '';
  END IF;
END $$;

-- The game server and the panel run as the koserver role: they must own what this file creates
-- (psql runs as postgres here, otherwise "permission denied for table info_panel_entry").
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'koserver') THEN
    ALTER TABLE info_panel_entry OWNER TO koserver;
  END IF;
END $$;
